   return (
    <table className={styles.registry_table}>
      <tbody>
        <tr> 
          <th>Felhasználónév</th>
          <th>Email</th>
          <th>Szerepkör</th>
          <th></th>
        </tr>
        {users ? (users.map(user => (
            <tr key={user.id}>
              <td>{user.username}</td>
              <td>{user.email}</td>
              <td>{user.role_name}</td>
              <td><button type="button" class="btn btn-danger">Törlés</button></td>
            </tr>
          ))
        ) : (
          <tr>
            <td colSpan="4">Betöltés...</td>
          </tr>
        )}
      </tbody>
    </table>
  );
}
